#!/bin/bash
# Suite: the generated emoji bundles as shipped data.
#
# The bundles are generated by bin/vb-emoji-gen, but they are committed: the
# picker must work offline with no generator, network or Python dependency.
# This suite checks the invariants the menu relies on - the lazy marker, the
# grid layout, the command, and that a value appears on exactly one page - so
# a regeneration that breaks search is caught without booting Quickshell.

source "$(dirname "${BASH_SOURCE[0]}")/../../lib/lib.sh"
source "$(dirname "${BASH_SOURCE[0]}")/../../lib/harness.sh"

t_init "emoji-bundle" "generated bundles: marker, grid layout, command, disjoint pages, no duplicate values"

require_tools node

EMOJI_DIR="$SHELL_DIR/features/pickers/emoji"
ENTRY="$EMOJI_DIR/emojis.jsonc"
COMPANION="$EMOJI_DIR/emojis-all.jsonc"

t_file "the entry bundle is shipped" "$ENTRY"
t_file "the search companion is shipped" "$COMPANION"

t_contains "the entry names its companion" "// lazy-search: emojis-all.jsonc" \
  "$(grep '^// lazy-search:' "$ENTRY")"
t_not_contains "the companion does not point at another file" 'lazy-search:' \
  "$(grep '^// lazy-search:' "$COMPANION")"

FACTS="$(node - "$ENTRY" "$COMPANION" <<'NODE'
const fs = require('fs')
const read = (path) => {
  const text = fs.readFileSync(path, 'utf8')
  return JSON.parse(text.replace(/^\s*\/\/.*$/gm, ''))
}
const entry = read(process.argv[2])
const companion = read(process.argv[3])
const ep = entry.pages[0]
const ap = companion.pages[0]
const values = (pg) => pg.items.map(i => i.value).filter(v => typeof v === 'string' && v !== '')
const e = values(ep)
const a = values(ap)
const all = e.concat(a)
const dup = all.length - new Set(all).size
const out = {
  entryLayout: ep.layout,
  companionLayout: ap.layout,
  entryMax: String(ep.maxHeight),
  companionMax: String(ap.maxHeight),
  command: ep.command,
  faces: String(e.length),
  rest: String(a.length),
  restBig: String(a.length > 1000),
  duplicates: String(dup),
  faceHint: String(ep.items.some(i => i.type === 'separator' && i.section !== '')),
}
for (const key of Object.keys(out)) console.log(key + '=' + out[key])
NODE
)"

fact() { printf '%s\n' "$FACTS" | sed -n "s/^$1=//p"; }

t_eq "the entry page is a grid" "grid" "$(fact entryLayout)"
t_eq "the companion is a grid" "grid" "$(fact companionLayout)"
t_eq "the entry has no page ceiling" "0" "$(fact entryMax)"
t_eq "the companion has no page ceiling" "0" "$(fact companionMax)"
t_eq "rows insert with the page command" "vb-emoji-insert %v" "$(fact command)"
t_eq "the entry lists faces" "132" "$(fact faces)"
t_eq "the companion carries the rest" "true" "$(fact restBig)"
t_eq "no emoji is indexed twice" "0" "$(fact duplicates)"
t_eq "the entry points at search with a grid section header" "true" "$(fact faceHint)"

t_summary
